/* Isolated NSApplication input queue; no CGEvent/global cursor/focus calls. */
#import <AppKit/AppKit.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
typedef struct{uint32_t magic,version,pending,msg[7];uint64_t polls,events;}Image;
typedef struct{uint32_t msg;int32_t x,y;uint32_t sequence,time_lo,time_hi;}EventRecord;
typedef struct{uint32_t magic,version,route,sequence;int32_t screen[2],client[2];uint32_t framework_count,input_count;int32_t trace[64][10];uint32_t queued;EventRecord records[32];}Route;
typedef struct{NSWindow*window;Image im;Route route;NSRect expected;__strong NSMutableArray*owned;}State;
static int matches(uint32_t m,uint32_t lo,uint32_t hi){return(!lo&&!hi)||(m>=lo&&m<=hi);}
static NSEventMask mask(uint32_t lo,uint32_t hi){if(!lo&&!hi)return NSEventMaskAny;NSEventMask m=0;if(matches(0x200,lo,hi))m|=NSEventMaskMouseMoved|NSEventMaskLeftMouseDragged|NSEventMaskRightMouseDragged;if(matches(0x201,lo,hi))m|=NSEventMaskLeftMouseDown;if(matches(0x202,lo,hi))m|=NSEventMaskLeftMouseUp;if(matches(0x204,lo,hi))m|=NSEventMaskRightMouseDown;if(matches(0x205,lo,hi))m|=NSEventMaskRightMouseUp;if(lo<=0x108&&hi>=0x100)m|=NSEventMaskKeyDown|NSEventMaskKeyUp|NSEventMaskFlagsChanged;return m;}
void*s45p_new(void*p){if(!p||!NSThread.isMainThread)return NULL;State*s=calloc(1,sizeof(*s));if(s){s->window=(__bridge NSWindow*)p;s->expected=s->window.frame;s->owned=[NSMutableArray new];s->im.magic=0x53343250;s->im.version=1;s->route.magic=0x52343550;s->route.version=1;}return s;}
static void trace(State*s,NSEvent*e,uint32_t action){uint32_t i=s->route.framework_count+s->route.input_count;if(i<64){NSRect f=s->window.frame;int32_t a[10]={(int32_t)e.type,(int32_t)e.subtype,(int32_t)e.windowNumber,(int32_t)s->window.windowNumber,e.window==s->window,action,(int32_t)f.origin.x,(int32_t)f.origin.y,(int32_t)f.size.width,(int32_t)f.size.height};memcpy(s->route.trace[i],a,sizeof(a));}}
static NSEvent*owned_event(State*s,EventRecord*r){NSView*v=s->window.contentView;NSPoint p=NSMakePoint(r->x,v.isFlipped?r->y:v.bounds.size.height-r->y);p=[v convertPoint:p toView:nil];NSEventType type=r->msg==0x200?NSEventTypeMouseMoved:r->msg==0x201?NSEventTypeLeftMouseDown:r->msg==0x202?NSEventTypeLeftMouseUp:0;uint64_t ticks=(uint64_t)r->time_lo|((uint64_t)r->time_hi<<32);return[NSEvent mouseEventWithType:type location:p modifierFlags:0 timestamp:(double)ticks/1000000.0 windowNumber:s->window.windowNumber context:nil eventNumber:0x450000+r->sequence clickCount:1 pressure:r->msg==0x201?1:0];}
int s45p_inject(State*s,uint32_t message,int32_t x,int32_t y){if(!s||!NSThread.isMainThread||s->route.queued>=32||x<0||y<0||x>=s->window.contentView.bounds.size.width||y>=s->window.contentView.bounds.size.height||NSApp.isActive||s->window.isKeyWindow)return -1;if(message!=0x200&&message!=0x201&&message!=0x202)return -2;uint64_t ticks=(uint64_t)(NSProcessInfo.processInfo.systemUptime*1000000.0);EventRecord r={message,x,y,++s->route.sequence,(uint32_t)ticks,(uint32_t)(ticks>>32)};NSEvent*e=owned_event(s,&r);if(!e||e.window!=s->window)return -3;NSPoint screen=[s->window convertPointToScreen:e.locationInWindow];s->route.route=1;s->route.screen[0]=(int32_t)screen.x;s->route.screen[1]=(int32_t)(NSMaxY(NSScreen.screens[0].frame)-screen.y);s->route.client[0]=x;s->route.client[1]=y;s->route.records[s->route.queued++]=r;[s->owned addObject:e];return 0;}
int s45p_pointer(State*s,int32_t*out){if(!s||!out||!s->route.route)return 0;memcpy(out,s->route.screen,8);return 1;}
int s45p_default(State*s,uint32_t h,uint32_t msg,uint32_t wp,uint32_t lp,uint32_t*out){if(!s||!out||h!=0x58000001||s->im.msg[0]!=h||s->im.msg[1]!=msg||s->im.msg[2]!=wp||s->im.msg[3]!=lp||(msg!=0x200&&msg!=0x201&&msg!=0x202))return 0;/* Client MOVE/UP has no default action. DOWN clears Alt/F10 menu latches; this isolated mouse-only route has none. */*out=0;return 1;}
int s45p_peek(State*s,uint32_t remove,uint32_t lo,uint32_t hi,uint32_t*out,uint32_t*diag){if(!s||!out||!diag||remove>1||!NSThread.isMainThread)return -1;BOOL active=NSApp.isActive,key=s->window.isKeyWindow;diag[0]=diag[1]=0;s->im.polls++;if(s->im.pending&&!matches(s->im.msg[1],lo,hi))return -6;
 if(!s->im.pending){NSEventMask requested=mask(lo,hi);if(!requested)return -7;NSEvent*e=nil;
  for(int attempt=0;attempt<32;attempt++){if(s->route.queued&&matches(s->route.records[0].msg,lo,hi)){e=s->owned[0];[s->owned removeObjectAtIndex:0];s->route.queued--;memmove(s->route.records,s->route.records+1,s->route.queued*sizeof(EventRecord));}else e=[NSApp nextEventMatchingMask:requested untilDate:NSDate.distantPast inMode:NSDefaultRunLoopMode dequeue:YES];if(active!=NSApp.isActive||key!=s->window.isKeyWindow)return -2;if(!e)return 0;diag[0]=(uint32_t)e.type;diag[1]=(uint32_t)e.subtype;
   if(e.type==NSEventTypeAppKitDefined&&e.subtype==NSEventSubtypeWindowMoved){trace(s,e,1);if(e.window!=s->window||!NSEqualRects(s->window.frame,s->expected)){[NSApp postEvent:e atStart:YES];return -8;}[NSApp sendEvent:e];s->route.framework_count++;if(active!=NSApp.isActive||key!=s->window.isKeyWindow)return -2;continue;}break;}
  uint32_t msg=0;switch(e.type){case NSEventTypeMouseMoved:case NSEventTypeLeftMouseDragged:case NSEventTypeRightMouseDragged:msg=0x200;break;case NSEventTypeLeftMouseDown:msg=0x201;break;case NSEventTypeLeftMouseUp:msg=0x202;break;case NSEventTypeRightMouseDown:msg=0x204;break;case NSEventTypeRightMouseUp:msg=0x205;break;default:break;}
  if(!msg||e.window!=s->window||!matches(msg,lo,hi)){[NSApp postEvent:e atStart:YES];return -5;}NSView*v=s->window.contentView;NSPoint p=[v convertPoint:e.locationInWindow fromView:nil];if(!v.isFlipped)p.y=v.bounds.size.height-p.y;NSPoint screen=[s->window convertPointToScreen:e.locationInWindow];int authored=e.eventNumber>0x450000&&e.eventNumber<=0x450000+s->route.sequence;uint32_t buttons=authored?0:(uint32_t)NSEvent.pressedMouseButtons;uint32_t wp=(buttons&1?1:0)|(buttons&2?2:0)|(e.modifierFlags&NSEventModifierFlagShift?4:0)|(e.modifierFlags&NSEventModifierFlagControl?8:0);if(msg==0x201)wp|=1;if(msg==0x202)wp&=~1u;
  int32_t x=(int32_t)p.x,y=(int32_t)p.y;s->im.msg[0]=0x58000001;s->im.msg[1]=msg;s->im.msg[2]=wp;s->im.msg[3]=(x&65535)|((y&65535)<<16);s->im.msg[4]=(uint32_t)(e.timestamp*1000);s->im.msg[5]=(int32_t)screen.x;s->im.msg[6]=(int32_t)(NSMaxY(NSScreen.screens[0].frame)-screen.y);s->im.pending=1;s->im.events++;trace(s,e,authored?3:2);s->route.input_count++;if(authored){s->route.route=1;s->route.screen[0]=s->im.msg[5];s->route.screen[1]=s->im.msg[6];s->route.client[0]=x;s->route.client[1]=y;}
 }memcpy(out,s->im.msg,sizeof(s->im.msg));if(remove)s->im.pending=0;return 1;}
size_t s45p_size(void){return sizeof(Image);}int s45p_export(State*s,void*p,size_t n){if(!s||!p||n!=sizeof(Image))return 0;memcpy(p,&s->im,n);return 1;}int s45p_import(State*s,const void*p,size_t n){if(!s||!p||n!=sizeof(Image))return 0;const Image*i=p;if(i->magic!=0x53343250||i->version!=1||i->pending>1)return 0;s->im=*i;return 1;}
size_t s45p_route_size(void){return sizeof(Route);}int s45p_route_export(State*s,void*p,size_t n){if(!s||n!=sizeof(Route))return 0;memcpy(p,&s->route,n);return 1;}int s45p_route_import(State*s,const void*p,size_t n){if(!s||(n!=sizeof(Route)&&n!=2600))return 0;Route r={0};memcpy(&r,p,n);if(r.magic!=0x52343550||r.version!=1||r.route>1||r.queued>32)return 0;[s->owned removeAllObjects];for(uint32_t i=0;i<r.queued;i++){NSEvent*e=owned_event(s,r.records+i);if(!e||e.window!=s->window)return 0;[s->owned addObject:e];}s->route=r;return 1;}
void s45p_delete(State*s){if(s){s->owned=nil;free(s);}}
